# 本ツールに取り込む際は、表記を「当行」に統一する（プリセットデータ・新規アップロードの両方に適用）。
# ※PRESET_FUNDSの初期化処理より前に定義する必要があるため、ファイル冒頭に配置している。
def normalize_conflict_of_interest_subject(text):
    if not text:
        return text
    return text.replace("当金庫", "当行").replace("当社", "当行")

