# AIの出力ゆらぎから「ファンドA」「ファンドB」などの仮名を完全排除するための自動置換フィルター
def replace_dummy_fund_names(text, selected_funds):
    if not selected_funds:
        return text
    
    # 完全にファンド名を一致させるため、一般的なゆらぎ表現を順次置換するリストを定義
    # 1番目のファンドに対応するダミー仮名
    dummies_a = [
        "ファンド名A", "ファンド A", "ファンドA", "Aファンド", "aファンド", 
        "ファンドa", "ファンド a", "ファンド（A）", "ファンド (A)", "（A）"
    ]
    # 2番目のファンドに対応するダミー仮名
    dummies_b = [
        "ファンド名B", "ファンド B", "ファンドB", "Bファンド", "bファンド", 
        "ファンドb", "ファンド b", "ファンド（B）", "ファンド (B)", "（B）"
    ]
    
    # 最も長い文字列パターンから安全に置換をかけます
    for d in dummies_a:
        text = text.replace(d, selected_funds[0])
        
    if len(selected_funds) > 1:
        for d in dummies_b:
            text = text.replace(d, selected_funds[1])
            
    return text


# JSON内のオブジェクトを含むすべてのネスト構造を再帰的に走査し、仮名を排除するフィルター
def clean_dummy_names_in_data(data, selected_funds):
    if not selected_funds:
        return data
        
    if isinstance(data, dict):
        new_data = {}
        for k, v in data.items():
            new_k = replace_dummy_fund_names(k, selected_funds)
            new_v = clean_dummy_names_in_data(v, selected_funds)
            new_data[new_k] = new_v
        return new_data
    elif isinstance(data, list):
        return [clean_dummy_names_in_data(item, selected_funds) for item in data]
    elif isinstance(data, str):
        return replace_dummy_fund_names(data, selected_funds)
        
    return data


# APIキーの設定 (APIKEY.ini または クラウドのSecretsからハイブリッド取得)
def load_api_key():
    config = configparser.ConfigParser()
    file_path = 'APIKEY.ini'
    if os.path.exists(file_path):
        try:
            config.read(file_path, encoding='utf-8-sig')
            key = config.get('GEMINI', 'API_KEY')
            return key.strip() if key else None
        except:
            pass
            
    try:
        if "GEMINI" in st.secrets and "API_KEY" in st.secrets["GEMINI"]:
            key = st.secrets["GEMINI"]["API_KEY"]
            return key.strip() if key else None
        elif "API_KEY" in st.secrets:
            key = st.secrets["API_KEY"]
            return key.strip() if key else None
    except:
        return None
        
    return None

INI_KEY = load_api_key()
EMBEDDED_API_KEY = INI_KEY


# 利用可能なモデルリストを安全に取得する関数 (リトライ機能内蔵 & キャッシュ化)
def get_available_models(api_key):
    if "available_models_list" in st.session_state and st.session_state.available_models_list:
        return st.session_state.available_models_list
        
    default_models = ['gemini-1.5-flash', 'gemini-1.5-pro', 'gemini-2.5-flash']
    if not api_key:
        return default_models

    # 無料枠制限（429）を考慮し、3回までリトライを試行
    for attempt in range(3):
        try:
            genai.configure(api_key=api_key)
            available = [m.name.replace('models/', '') for m in genai.list_models() if 'generateContent' in m.supported_generation_methods]
            if available:
                cleaned = [m for m in available if "gemini" in m]
                if cleaned:
                    st.session_state.available_models_list = cleaned
                    return cleaned
            return default_models
        except (exceptions.ResourceExhausted, Exception) as e:
            error_msg = str(e)
            if "429" in error_msg or isinstance(e, exceptions.ResourceExhausted):
                wait_time = (attempt + 1) * 3
                time.sleep(wait_time)
                continue
            return default_models
    return default_models


def get_safe_model_name(api_key):
    if "target_model_name" in st.session_state and st.session_state.target_model_name:
        return st.session_state.target_model_name

    models = get_available_models(api_key)
    has_flash = any('gemini-1.5-flash' in m for m in models)
    target = 'gemini-1.5-flash' if has_flash else (models[0] if models else 'gemini-1.5-flash')
    
    st.session_state.target_model_name = target
    return target


# PDFからテキストを抽出する関数
def extract_from_pdf(file):
    file.seek(0)
    reader = PdfReader(file)
    raw_text = "\n".join([page.extract_text() for page in reader.pages if page.extract_text()])
    return normalize_conflict_of_interest_subject(raw_text)


# --- 🏦 「（当行/当社/当金庫等）の利益とお客様の利益が反する可能性」の主語統一ルール ---
# 販売会社の呼称は銀行・信用金庫等によって「当行」「当社」「当金庫」等とまちまちだが、
# 本ツールに取り込む際は、表記を「当行」に統一する（プリセットデータ・新規アップロードの両方に適用）。
# 重要情報シートテキストを解析してファンド名を特定する関数 (リトライ機能内蔵)
def extract_fund_name_via_ai(text, default_name, api_key):
    for attempt in range(5):
        try:
            genai.configure(api_key=api_key)
            target_model = get_safe_model_name(api_key)
            model = genai.GenerativeModel(target_model)
            
            prompt = f"""
以下は、ユーザーからアップロードされた投資信託の「重要情報シート」テキストです。
この資料の【金融商品の名称、種類】という項目、またはそれに類する箇所に記載されている「ファンド名（投資信託の商品名）」を日本語で1つだけ見つけ出してください。
余計な説明、前置き, 記号、拡張子などは絶対に含めず、純粋な名称のみを返してください。
最大でも40文字以内とします。特定が難しい場合は「{default_name}」を返してください。

【資料テキストの一部】
{text[:2000]}
"""
            response = model.generate_content(prompt)
            res_text = response.text.strip()
            res_text = re.sub(r"[`'\"]", "", res_text)
            res_text = res_text.split("\n")[0].strip()
            return res_text if res_text else default_name
        except (exceptions.ResourceExhausted, Exception) as e:
            error_msg = str(e)
            if "429" in error_msg or isinstance(e, exceptions.ResourceExhausted):
                wait_time = (attempt + 1) * 10
                try:
                    st.toast(f"🤖 ロボより: 解析の制限（429）を検知いたしました。{wait_time}秒後に自動で再試行いたします（試行 {attempt + 1}/5）...")
                except:
                    pass
                time.sleep(wait_time)
                continue
            return default_name
            
    return default_name


# 重要情報シートテキストを解析して運用会社名を特定する関数 (リトライ機能内蔵)
def extract_company_name_via_ai(text, default_name, api_key):
    for attempt in range(5):
        try:
            genai.configure(api_key=api_key)
            target_model = get_safe_model_name(api_key)
            model = genai.GenerativeModel(target_model)
            
            prompt = f"""
以下は、投資信託の「重要情報シート」テキストです。
この資料の【組成会社（運用会社）】、あるいはそれに類する「委託会社」や「投資信託委託業者」、「アセットマネジメント」の箇所に記載されている「運用会社名」を日本語で1つだけ見つけ出してください。
（例：三菱UFJアセットマネジメント、アセットマネジメントOne、ニッセイアセットマネジメント、日興アセットマネジメント、インベスコ・アセット・マネジメント、野村アセットマネジメントなど）
余計な説明、前置き、記号などは絶対に含めず、純粋な組織名・会社名のみを返してください。
最大でも30文字以内とします。特定が難しい場合は「{default_name}」を返してください。

【資料テキストの一部】
{text[:2000]}
"""
            response = model.generate_content(prompt)
            res_text = response.text.strip()
            res_text = re.sub(r"[`'\"]", "", res_text)
            res_text = res_text.split("\n")[0].strip()
            return res_text if res_text else default_name
        except (exceptions.ResourceExhausted, Exception) as e:
            error_msg = str(e)
            if "429" in error_msg or isinstance(e, exceptions.ResourceExhausted):
                wait_time = (attempt + 1) * 10
                try:
                    st.toast(f"🤖 ロボより: 運用会社特定のための接続制限（429）を検知いたしました。{wait_time}秒後に自動で再試行いたします（試行 {attempt + 1}/5）...")
                except:
                    pass
                time.sleep(wait_time)
                continue
            return default_name
            
    return default_name


# AI回答・データ抽出ロジック (自動リトライ構造を確実に維持)
def get_ai_comparison_data(selected_funds_data, api_key, mode="table", mismatch_warnings=None, target_instruction=None):
    target_model = get_safe_model_name(api_key)
    
    # 選択されたファンドの重要情報シートテキストを結合
    combined_context = ""
    for name, text in selected_funds_data.items():
        combined_context += f"\n\n--- 【ファンド名: {name}】の重要情報シート ---\n{text}\n"

    # 動的なプレースホルダー差し替えによる安全なプロンプト合成
    if mode == "table":
        system_prompt = st.session_state.system_prompt_table.replace("{combined_context}", combined_context)
    else:
        # 解説文章の場合は、ターゲット設定（target_instruction）をプロンプト内に安全にインジェクション
        raw_system_prompt = st.session_state.system_prompt_analysis
        if target_instruction:
            raw_system_prompt = raw_system_prompt.replace("{target_persona_instruction}", target_instruction)
        else:
            raw_system_prompt = raw_system_prompt.replace("{target_persona_instruction}", "")
            
        system_prompt = raw_system_prompt.replace("{combined_context}", combined_context)
        
        # もしファンド間で基準日のズレ・不一致警告が存在する場合は、AIのシステムプロンプトの先頭に動的指示をインジェクション
        if mismatch_warnings:
            warning_bullets = "\\n".join([f"・{w}" for w in mismatch_warnings])
            dynamic_instruction = f"""
【最優先AI動的指示：現在、比較対象 of ファンド間で以下の算出基準日・期間にズレ（食い違い）がシステムによって検出されています。】
{warning_bullets}
これにより、実績リターン数値を単純比較してどちらが優れているかを安易に述べるのは非常に危険です。
解説文中の実績リターンの比較を行う箇所で、必ず「各ファンドで算出基準日や測定期間が異なっているため、単純な数値 of 大小比較には注意を払う必要があります」という軽めの言及・注意喚起を優しく含めてください。
"""
            system_prompt = dynamic_instruction + "\n" + system_prompt

    # 有償枠でも過度なリクエストで発生する一時的な制限を優しくハンドリングして自動リトライ
    for attempt in range(5):
        try:
            genai.configure(api_key=api_key)
            
            # テーブル（JSON）抽出モード・解説（analysis）モードともにJSON形式での出力を強制する
            model = genai.GenerativeModel(
                target_model,
                generation_config={"response_mime_type": "application/json"}
            )
                
            response = model.generate_content(system_prompt)
            return response.text

        except (exceptions.ResourceExhausted, Exception) as e:
            error_msg = str(e)
            if "429" in error_msg or isinstance(e, exceptions.ResourceExhausted):
                wait_time = (attempt + 1) * 10
                try:
                    is_custom = bool(st.session_state.get("custom_key", "").strip())
                    key_type_str = "有償カスタムキー" if is_custom else "既定 of システムキー"
                    st.toast(f"🤖 ロボより: APIレート制限（429）を検知いたしました（利用中の鍵: {key_type_str}）。{wait_time}秒後に自動で再試行いたしますので、そのまま少々お待ちください（試行 {attempt + 1}/5）...")
                except:
                    pass
                time.sleep(wait_time)
                continue
            return f"【システムエラー】詳細: {error_msg}"
            
    return "【混雑エラー】現在AIへのリクエストが連続しております。時間をおいて再実行してください。"


# 各行のテキストを数値化して投資家にとって有利なセル(最小値・最大値)を返すパーサー
def extract_min_max_indices(row, mode="min"):
    vals = []
    
    # row が pandas.Series または Python の標準リストいずれであっても対応
    is_series = hasattr(row, 'iloc')
    length = len(row)
    
    # 1列目は項目名なので除外し、各ファンドの列を評価
    for i in range(1, length):
        val_str = str(row.iloc[i]).strip() if is_series else str(row[i]).strip()
        if not val_str or "記載なし" in val_str or "抽出スキップ" in val_str:
            continue
            
        # 🌟 無料（手数料ゼロ）を意味するキーワード。
        # ユーザー指摘の「かかりません」を筆合に、不要、発生、無料、なし、ゼロなどを徹底網羅
        free_keywords = ["なし", "無料", "ゼロ", "ノーロード", "かかりません", "発生しません", "不要", "負担いただきません", "かからず", "かかりません。"]
        if any(keyword in val_str for keyword in free_keywords) or val_str == "0" or val_str == "0.0":
            val = 0.0
            vals.append((i, val))
            continue
            
        # 1. パーセンテージ表記（%の直前にある数値）を最優先で抽出
        pct_matches = re.findall(r"([-+]?\d*\.\d+|\d+)\s*[%％]", val_str)
        if pct_matches:
            val = float(pct_matches[0])
            vals.append((i, val))
            continue
            
        # 2. パーセンテージ表記（%）が直接見つからない場合は、一般的な数値を抽出（小数値を優先）
        matches = re.findall(r"[-+]?\d*\.\d+|\d+", val_str)
        if matches:
            decimals = [float(m) for m in matches if '.' in m]
            if decimals:
                val = decimals[0]
            else:
                val = float(matches[0])
            vals.append((i, val))
        
    if not vals:
        return []
        
    # ベストパフォーマンス値（リターン is 最大値、コスト・手数料は最小値）を算出
    if mode == "min":
        best_val = min(v[1] for v in vals)
    else:
        best_val = max(v[1] for v in vals)
        
    # ベストパフォーマンス値を保持しているすべての列インデックスのリストを特定
    best_indices = [v[0] for v in vals if v[1] == best_val]
    
    return best_indices


# --- 🌟 コンパクト比較表（デフォルト6項目）用の補助関数群 ---

def extract_first_percent(text):
    """文字列中から最初に出現する『%の数値』を抽出。無料系キーワードの場合は0.0を返す。見つからない場合はNoneを返す。"""
    if not text:
        return None
    val_str = str(text).strip()
    free_keywords = ["なし", "無料", "ゼロ", "ノーロード", "かかりません", "発生しません", "不要", "負担いただきません", "かからず"]
    if any(k in val_str for k in free_keywords):
        return 0.0
    matches = re.findall(r"([-+]?\d*\.\d+|\d+)\s*[%％]", val_str)
    if matches:
        try:
            return float(matches[0])
        except ValueError:
            return None
    return None


def compute_effective_cost(purchase_fee_text, trust_fee_text):
    """購入時手数料と信託報酬（年率）を「見た目の実質コスト」として1つの文字列にまとめる。
    ※あくまで概算の目安であり、購入時手数料（一時的）と信託報酬（継続的）を単純合算した参考値である旨を明記する。"""
    purchase_pct = extract_first_percent(purchase_fee_text)
    trust_pct = extract_first_percent(trust_fee_text)

    if purchase_pct is not None and trust_pct is not None:
        total = purchase_pct + trust_pct
        return f"目安 {total:.3f}%（購入時{purchase_pct:g}% + 信託報酬{trust_pct:g}%）"
    elif trust_pct is not None:
        return f"信託報酬 年{trust_pct:g}%（購入時手数料：記載なし）"
    elif purchase_pct is not None:
        return f"購入時{purchase_pct:g}%（信託報酬：記載なし）"
    else:
        return "記載なし（抽出スキップ）"


def simplify_nisa(nisa_text):
    """詳細なNISA区分の文言から『対象の有無』のみを簡潔に判定して返す。"""
    if not nisa_text:
        return "記載なし（抽出スキップ）"
    text = str(nisa_text).strip()
    if "記載なし" in text or "抽出スキップ" in text:
        return text
    no_keywords = ["対象外", "対象ではありません", "適用されません", "非対象", "なし"]
    if any(k in text for k in no_keywords) and not any(k in text for k in ["つみたて", "成長投資枠"]):
        return "対象外"
    # 対象の場合、可能であれば枠の種類も併記する
    types = []
    if "つみたて" in text:
        types.append("つみたて投資枠")
    if "成長投資枠" in text:
        types.append("成長投資枠")
    if types:
        return "対象（" + "・".join(types) + "）"
    return "対象"


def parse_numeric_value(text):
    """文字列から数値（%表記優先）を1つ抽出してfloatで返す。抽出できない場合はNoneを返す。"""
    if text is None:
        return None
    val_str = str(text).strip()
    if not val_str or "記載なし" in val_str or "抽出スキップ" in val_str:
        return None
    matches = re.findall(r"([-+]?\d*\.\d+|\d+)\s*[%％]", val_str)
    if matches:
        try:
            return float(matches[0])
        except ValueError:
            return None
    matches2 = re.findall(r"[-+]?\d*\.\d+|\d+", val_str)
    if matches2:
        try:
            return float(matches2[0])
        except ValueError:
            return None
    return None


def get_cell(df, item_name, fund_name):
    """比較表DataFrameから、指定した項目名・ファンド名に対応するセルの値を取得する。"""
    try:
        row = df[df["比較項目（行）"] == item_name]
        if row.empty or fund_name not in df.columns:
            return "記載なし（抽出スキップ）"
        return row.iloc[0][fund_name]
    except Exception:
        return "記載なし（抽出スキップ）"


# --- 🎯 顧客属性による候補ファンドの絞り込み（AIを使わない、コード側の決定的なルールベース判定） ---
# ※選定ロジックそのものはAIの自由生成に一切依存させず、重要情報シートの原文に含まれる
#   キーワード・数値の有無のみで判定することで、再現性・検証可能性を担保している。
RISKY_KEYWORDS = ["新興国", "レバレッジ", "カントリーリスク", "インド", "テクノロジー", "脱炭素", "ハイイールド", "信用リスクが高", "元本超過"]

# 自由記述欄からキーワードを拾う際に除外する一般的な語（助詞・付属語・定型表現など）
FREE_TEXT_STOPWORDS = {
    "こと", "ため", "もの", "よう", "これ", "それ", "あの", "この", "です", "ます",
    "して", "いる", "ある", "なる", "たい", "など", "という", "ください", "予定",
    "希望", "場合", "くらい", "ぐらい", "ので", "から", "また", "そして", "しかし",
    "資金", "運用", "投資", "商品", "対象", "検討", "考え", "少なめ", "多め", "当面",
    "ファンド", "その他", "以外", "選択", "選択したい", "銘柄", "タイプ", "保有",
    "保有している", "持っている", "すでに", "既に", "現在", "自身", "本人",
}


def extract_keywords_from_free_text(text, min_len=2):
    """自由記述欄から、判定に使えそうな単語（キーワード）を簡易的に抽出する。
    ※形態素解析は行わず、句読点＋代表的な助詞での分割による簡易処理のため、
    完全な精度は保証されないが、ESGや教育資金・住宅ローンといった特徴的な語は概ね拾える。"""
    if not text:
        return []
    rough_tokens = re.split(r"[、。・/\s,.()（）\n【】「」]+", text)
    keywords = []
    for rt in rough_tokens:
        sub_tokens = re.split(r"(?:について|に関心|に関する|のため|によって|とともに|している|は|が|を|に|の|で|と|へ|から|まで|より|も|や)", rt)
        for st in sub_tokens:
            st = st.strip()
            if len(st) >= min_len and st not in FREE_TEXT_STOPWORDS:
                keywords.append(st)
    # 重複除去（出現順は維持）
    seen = set()
    result = []
    for k in keywords:
        if k not in seen:
            seen.add(k)
            result.append(k)
    return result


# --- 🧭 自由記述の意味合い（肯定的な関心か、除外したい否定的なニュアンスか）を判定するルール ---
# ※AIによる自由な意味解釈は行わず、あらかじめ定義した「手がかり語（cue words）」が
#   同じ節（クローズ）内に存在するかどうかのみで判定する、決定的（deterministic）なロジック。
NEGATION_CUES = [
    "避けたい", "苦手", "嫌い", "不要", "除きたい", "除外したい", "したくない",
    "興味がない", "望まない", "求めない", "多すぎる", "は嫌", "NG", "ダメ",
    "控えたい", "抵抗がある", "心配", "不安", "怖い", "リスクが高すぎる", "リスクを取りたくない",
    "保有している", "持っている", "すでに保有", "既に保有", "保有中", "保有済み",
    "既に持って", "持っています", "別のファンドで", "他のファンドで", "その他のファンドで",
]
POSITIVE_CUES = [
    "興味がある", "重視", "希望", "好き", "気になる", "検討したい",
    "求める", "優先", "興味を持って", "積極的に", "前向き", "魅力を感じ",
]


def analyze_free_text_sentiment(free_text):
    """自由記述を句点(。)単位の『節』に分割し、各節に含まれるキーワードについて、
    同じ節内にある手がかり語(NEGATION_CUES / POSITIVE_CUES)の有無から、
    そのキーワードが『肯定的な関心事』なのか『除外したい否定的な事柄』なのかを判定する。
    否定・肯定どちらの手がかり語も見つからない場合は、単に言及されているだけとみなし『肯定的』寄りに扱う
    （自由記述に書く内容は、基本的に前向きな関心事や重視したい点であることが多いため）。
    戻り値：[{"keyword": str, "sentiment": "positive"|"negative", "clause": str}, ...]"""
    if not free_text or not free_text.strip():
        return []

    clauses = [c.strip() for c in re.split(r"[。\n]", free_text) if c.strip()]
    results = []
    seen = set()
    for clause in clauses:
        keywords = extract_keywords_from_free_text(clause)
        if not keywords:
            continue
        has_negation = any(cue in clause for cue in NEGATION_CUES)
        has_positive = any(cue in clause for cue in POSITIVE_CUES)
        # 否定手がかりが存在する場合は「否定的」を優先する（肯定手がかりと同じ節に混在していても、
        # 除外・保有済み等の否定的意向のほうが実務上重要度が高いため）。
        # 否定手がかりが無く、肯定手がかりがある場合、またはどちらも無い場合は「肯定的」寄りに扱う。
        sentiment = "negative" if has_negation else "positive"
        for kw in keywords:
            if kw in seen:
                continue
            seen.add(kw)
            results.append({"keyword": kw, "sentiment": sentiment, "clause": clause})
    return results


# --- 🗂️ ファンド分類（投資対象の分類）の判定（AIを使わない、キーワードベースの決定的分類） ---
FUND_CATEGORY_RULES = [
    ("全世界株式型", ["全世界", "オール・カントリー", "オルカン"]),
    ("米国株式型", ["米国株式", "S&P500", "S&P 500", "米国の企業"]),
    ("先進国株式型", ["先進国の株式", "先進国株式"]),
    ("インド株式型", ["インド"]),
    ("新興国株式型", ["新興国"]),
    ("国内株式型", ["日本株式", "TOPIX", "東証株価指数", "日経平均", "225"]),
    ("テーマ型株式（脱炭素・環境）", ["脱炭素", "カーボン"]),
    ("テーマ型株式（テクノロジー）", ["テクノロジー", "ロボティクス"]),
    ("バランス型（複合資産）", ["REIT", "不動産投資信託証券"]),
    ("債券型", ["ソブリン", "ボンド", "債券"]),
]


def classify_fund_type(text):
    """ファンドの原文テキストから、投資対象の分類（ファンド分類）を判定する。
    複数のルールに合致する場合は、上に定義した順序（より具体的な分類を優先）で最初に一致したものを採用する。"""
    if not text:
        return "その他・分類不明"
    for category, keywords in FUND_CATEGORY_RULES:
        if any(k in text for k in keywords):
            return category
    return "その他・分類不明"


# --- 🎯 コア・サテライト運用の考え方に基づく分類（AIを使わない、キーワードベースの決定的判定） ---
# サテライト資産：テーマ型ファンド、新興国株式・債券、REIT、ハイ・イールド債、ブル・ベア型、オルタナティブ投資等
# コア資産：それ以外（全世界株式・先進国株式・国内株式・伝統的な債券インデックス 等）
#
# ※ classify_fund_type() が判定した「投資対象の分類」を土台にしている。単純なキーワードの有無だけで判定すると、
#   例えば「オルカン」のように全世界（先進国＋新興国）に分散投資するコア的な商品が、説明文中に
#   「新興国」という語を含むというだけで誤って『サテライト資産』に分類されてしまう問題があったため、
#   classify_fund_type が優先順位をつけて判定した「最も具体的な分類カテゴリ」をそのまま利用することで、
#   このような誤判定を避けている。
SATELLITE_CATEGORIES = {
    "新興国株式型", "インド株式型",
    "テーマ型株式（脱炭素・環境）", "テーマ型株式（テクノロジー）",
    "バランス型（複合資産）",  # REITを含む複合資産型。ご指定の定義（REIT＝サテライト資産）に基づく
}
# classify_fund_type のカテゴリ体系に含まれない、追加のサテライト要素（原文キーワードで直接判定）
SATELLITE_EXTRA_KEYWORDS = [
    "ハイイールド", "ハイ・イールド", "高利回り債",
    "ブル型", "ベア型", "ブル・ベア", "ブルベア",
    "オルタナティブ", "コモディティ", "商品先物", "ヘッジファンド", "プライベートエクイティ",
]


def classify_core_satellite(text):
    """コア・サテライト運用の考え方に基づき、ファンドを『コア資産』『サテライト資産』のいずれかに分類する。
    定義：サテライト資産＝テーマ型ファンド・新興国株式/債券・REIT・ハイイールド債・ブル/ベア型・オルタナティブ投資等。
    上記に該当しないものはすべて『コア資産』として扱う。"""
    if not text:
        return "コア資産"
    category = classify_fund_type(text)
    if category in SATELLITE_CATEGORIES:
        return "サテライト資産"
    if any(k in text for k in SATELLITE_EXTRA_KEYWORDS):
        return "サテライト資産"
    return "コア資産"


def score_and_narrow_funds(fund_list, uploaded_funds, hearing, top_n=5):
    """全ファンドの原文テキストと、ヒアリングで得た顧客属性を照合し、
    ルールベースのスコアリングにより候補を上位N件に絞り込む。
    戻り値：[{"fund": ファンド名, "score": 点数, "reasons": [根拠文字列, ...]}, ...]（スコア降順）"""
    free_text_items = analyze_free_text_sentiment(hearing.get("free_text", ""))

    results = []
    for name in fund_list:
        data = uploaded_funds.get(name, {})
        text = data.get("text", "") if isinstance(data, dict) else str(data)
        score = 0
        reasons = []

        # ① 信託報酬（コスト）の抽出
        trust_match = re.search(r"信託報酬[^\d]{0,25}(\d+\.?\d*)\s*[%％]", text)
        trust_pct = float(trust_match.group(1)) if trust_match else None

        # ② リスク許容度との照合
        risk_hits = sum(1 for k in RISKY_KEYWORDS if k in text)
        tol = hearing.get("tolerance_level", "普通")
        if tol == "低い":
            if risk_hits == 0:
                score += 3
                reasons.append(f"【リスク許容度】お客様のご回答「{hearing.get('tolerance_raw', tol)}」に対し、新興国・レバレッジ型などの値動きの大きい資産を含まないため合致")
            else:
                score -= 3 * risk_hits
        elif tol == "高い":
            if risk_hits >= 1:
                score += 2
                reasons.append(f"【リスク許容度】お客様のご回答「{hearing.get('tolerance_raw', tol)}」に対し、積極的な運用を志向する値動きの大きい資産を含むため合致")
        else:  # 普通
            if risk_hits <= 1:
                score += 1
                reasons.append(f"【リスク許容度】お客様のご回答「{hearing.get('tolerance_raw', tol)}」に対し、過度に値動きの大きい資産（新興国・レバレッジ型等）を含まない標準的なリスク水準のため合致")

        # ③ コスト（低コストをやや優遇。ただし決定的な足切りにはしない）
        if trust_pct is not None:
            if trust_pct < 0.5:
                score += 1.5
                reasons.append(f"【コスト】信託報酬が年率{trust_pct:g}%と低水準であるため、コストを抑えたいニーズに合致")
            elif trust_pct > 1.5 and tol == "低い":
                score -= 1

        # ④ NISA活用意向との照合
        nisa_pref = hearing.get("nisa_pref", "")
        if nisa_pref == "つみたて投資枠を使いたい" and "つみたて投資枠" in text:
            score += 2
            reasons.append(f"【NISA活用意向】お客様のご希望「{nisa_pref}」に対し、NISAつみたて投資枠の対象商品であるため合致")
        elif nisa_pref == "成長投資枠を使いたい" and "成長投資枠" in text:
            score += 2
            reasons.append(f"【NISA活用意向】お客様のご希望「{nisa_pref}」に対し、NISA成長投資枠の対象商品であるため合致")

        # ⑤ 為替リスク許容度との照合
        fx_pref = hearing.get("fx_tolerance", "")
        has_fx_exposure = any(k in text for k in ["為替変動リスク", "外国", "為替ヘッジなし"])
        if fx_pref == "為替リスクは避けたい（国内資産中心）":
            if not has_fx_exposure:
                score += 2
                reasons.append(f"【為替リスク許容度】お客様のご希望「{fx_pref}」に対し、為替変動リスクの記載がない国内資産中心の商品であるため合致")
            else:
                score -= 2

        # ⑥ 投資目的との照合（インカムゲイン重視の場合、毎月決算型・分配重視型を優先）
        purpose = hearing.get("purpose", "")
        if "インカムゲイン" in purpose or "分配" in purpose:
            if any(k in text for k in ["毎月決算", "毎月分配", "分配重視"]):
                score += 3
                reasons.append(f"【投資目的】お客様のご希望「{purpose}」に対し、毎月決算型・分配重視型の商品であるため合致")

        # ⑥.5 コア・サテライト運用の考え方との照合
        # 定義：サテライト資産＝テーマ型ファンド・新興国株式/債券・REIT・ハイイールド債・ブル/ベア型・オルタナティブ投資等。それ以外はコア資産。
        core_sat_pref = hearing.get("core_satellite_pref", "特にこだわらない")
        fund_core_sat = classify_core_satellite(text)
        if core_sat_pref.startswith("コア資産（"):
            if fund_core_sat == "コア資産":
                score += 3
                reasons.append(f"【コア・サテライト】お客様のご希望「コア資産を中心に安定運用したい」に対し、本ファンドは全世界・先進国・国内株式や伝統的債券等の『コア資産』に分類されるため合致")
            else:
                score -= 3
                reasons.append(f"【コア・サテライト】お客様のご希望「コア資産を中心に安定運用したい」に対し、本ファンドはテーマ型・新興国・REIT・ハイイールド債等の『サテライト資産』に分類されるため減点")
        elif core_sat_pref.startswith("コア資産をベースに"):
            reasons.append(f"【コア・サテライト】お客様のご希望「コア資産をベースにサテライト資産も一部取り入れたい」に対し、本ファンドは『{fund_core_sat}』に分類されます（コア・サテライト双方をバランス良く組み合わせる観点でご検討ください）")
        elif core_sat_pref.startswith("サテライト資産も積極的に"):
            if fund_core_sat == "サテライト資産":
                score += 3
                reasons.append(f"【コア・サテライト】お客様のご希望「サテライト資産も積極的に組み入れ、プラスアルファのリターンを狙いたい」に対し、本ファンドはテーマ型・新興国・REIT等の『サテライト資産』に分類され、積極的なリターン追求のニーズに合致")

        # ⑦ 除外したい条件（こだわり条件）との照合
        for tag in hearing.get("avoid_tags", []):
            if tag and tag in text:
                score -= 5
                reasons.append(f"【除外条件】お客様が除外を希望された「{tag}」に該当する記載があるため大幅減点（このファンドは条件に合致しない可能性が高い点にご注意ください）")

        # ⑧ 自由記述欄のキーワード照合（肯定的な関心事か、除外したい否定的な事柄かを手がかり語から判定）
        positive_matches = [item for item in free_text_items if item["sentiment"] == "positive" and item["keyword"] in text]
        negative_matches = [item for item in free_text_items if item["sentiment"] == "negative" and item["keyword"] in text]

        if positive_matches:
            score += 4 * len(positive_matches)
            for item in positive_matches:
                reasons.append(f"【自由記述】お客様のメモ「{item['clause']}」というご関心（キーワード：{item['keyword']}）に関連する記載がファンドの説明にあるため合致")

        if negative_matches:
            score -= 6 * len(negative_matches)
            for item in negative_matches:
                reasons.append(f"【自由記述】お客様のメモ「{item['clause']}」という除外のご意向（キーワード：{item['keyword']}）に該当する記載があるため大幅減点（このファンドは条件に合致しない可能性が高い点にご注意ください）")

        results.append({"fund": name, "score": round(score, 1), "reasons": reasons})

    results.sort(key=lambda x: x["score"], reverse=True)
    return results[:top_n]


