# 自作の高機能インタラクティブHTML比較テーブルのレンダリング関数
def render_custom_html_table(comparison_df, parsed_data):
    cols = comparison_df.columns.tolist()  # ['比較項目（行）', 'ファンドA', 'ファンドB']
    rows = comparison_df.values.tolist()

    # テーブル全体の列幅を100%に均等分割しつつ固定レイアウト（table-layout: fixed）にして、ファンド列の横幅を完全に均一化
    num_cols = len(cols)
    first_col_width = 30  # 比較項目行は30%幅を確保
    other_col_width = (100 - first_col_width) / (num_cols - 1) if num_cols > 1 else 100

    # 外部CSSクラス「custom-comparison-table」をテーブル本体に割り当て
    html = '<table class="custom-comparison-table" style="width:100%; table-layout: fixed; border-collapse: collapse; font-size: 19px;">'
    
    # ヘッダーレンダリング
    html += '<thead><tr style="background-color: #eaeded; color: #1a1a1a; font-weight: bold; border-bottom: 2px solid #d1d5db;">'
    for c_idx, c in enumerate(cols):
        w = first_col_width if c_idx == 0 else other_col_width
        html += f'<th style="padding: 15px; border: 1px solid #d1d5db; text-align: center; font-size: 20px; width: {w}%;">{c}</th>'
    html += '</tr></thead>'
    
    # ボディレンダリング
    html += '<tbody>'
    for r_idx, row_data in enumerate(rows):
        item_name = row_data[0]

        # ハイライトセル（最良コスト（min）、最良リターン（max））の判定用
        best_indices = []
        if "対象期間・基準日" not in item_name:
            if any(k in item_name for k in ["リターン", "収益率", "利益率"]) and "実績値" in item_name:
                best_indices = extract_min_max_indices(row_data, mode="max")
            elif any(k in item_name for k in ["信託報酬", "手数料", "コスト"]):
                best_indices = extract_min_max_indices(row_data, mode="min")
                
        # 各行の出力
        html += f'<tr style="border-bottom: 1px solid #d1d5db;">'
        for c_idx, val in enumerate(row_data):
            if c_idx == 0:
                html += f'<td style="padding: 15px; border: 1px solid #d1d5db; font-weight: bold; color: #0f4c75; word-wrap: break-word;">{val}</td>'
            else:
                # ユーザー要求に基づき、優良数値セルに対して専用スタイル用CSSクラス「custom-highlight-cell」を付加
                if c_idx in best_indices:
                    html += f'<td class="custom-highlight-cell" style="padding: 15px; border: 1px solid #d1d5db; word-wrap: break-word;">{val}</td>'
                else:
                    html += f'<td style="padding: 15px; border: 1px solid #d1d5db; word-wrap: break-word;">{val}</td>'
        html += '</tr>'
        
    html += '</tbody></table>'
    return html


