    st.markdown("<div style='margin-top: 25px;'></div>", unsafe_allow_html=True)

    # 3. PDFアップローダー
    with st.container(border=True):
        st.markdown("<h4 style='font-size: 24px; margin-bottom: 15px;'>📁 重要情報シート PDFアップロード (手動追加用)</h4>", unsafe_allow_html=True)
        st.markdown("<p style='font-size: 18px; color: #555555; margin-bottom: 15px;'>プリセットされた5ファンドの他に、新しく別の重要情報シートPDFを追加して同時に比較させたい場合は、以下からドラッグ＆ドロップしてアップロードしてください。</p>", unsafe_allow_html=True)
