            st.success(f"現在、合計 {len(st.session_state.uploaded_funds)} 件 of ファンド情報が登録されております。")
            
            # 登録直後に直感的ステップで進める誘導ボタン
            st.markdown("<div style='margin-top: 20px;'></div>", unsafe_allow_html=True)
            if st.button("➡️ 比較するファンドの選択へ進む", key="go_to_selection_from_admin"):
                st.session_state.current_page = "selection"
