            reason_map = {r["fund"]: r["reasons"] for r in narrowing_results}
            st.markdown("##### ✅ 絞り込み結果（チェックを調整して最終確定できます）")
            for idx, r in enumerate(narrowing_results):
                fund_name = r["fund"]
                fund_data = st.session_state.uploaded_funds.get(fund_name, {})
