# STEP 3 : 比較結果表示および自動解説
# AI解説レポート（JSON構造）を「サマリーカード＋重要度別カードUI＋折りたたみ詳細」で描画する関数
def render_analysis_report(parsed_analysis, selected_funds):
    # 万が一、辞書型以外（パース失敗時のフォールバック含む）が渡された場合の防御的処理
    if not isinstance(parsed_analysis, dict):
        parsed_analysis = {}

    # 仮名混入防止フィルターをJSON構造全体に再帰適用
    parsed_analysis = clean_dummy_names_in_data(parsed_analysis, selected_funds)

    summary_text = parsed_analysis.get("summary") or "サマリーを生成できませんでした。時間をおいて再度お試しください。"
    key_points = parsed_analysis.get("key_points") or []
    conclusion_text = parsed_analysis.get("conclusion") or "まとめを生成できませんでした。時間をおいて再度お試しください。"

    # --- ① 結論サマリーカード（常時表示・担当者が一目で把握できる要約） ---
    st.markdown(f"""
    <div class="summary-card">
        <div class="summary-label">📌 結論サマリー（まずはここだけ読めばOK）</div>
        <div class="summary-text">{summary_text}</div>
    </div>
    """, unsafe_allow_html=True)

    importance_style = {
        "high":   {"card": "importance-high",   "badge": "badge-high",   "label": "🔴 重要"},
        "medium": {"card": "importance-medium", "badge": "badge-medium", "label": "🟠 注意"},
        "low":    {"card": "importance-low",    "badge": "badge-low",    "label": "⚪ 参考"},
    }

    # --- ② 詳細（選定の着眼点・まとめ）は折りたたみ表示（デフォルトは閉じた状態） ---
    with st.expander("📋 詳細な選定の着眼点・まとめを見る（クリックで展開）", expanded=False):
        if not key_points:
            st.info("着眼点データを取得できませんでした。時間をおいて再度お試しください。")
        else:
            for kp in key_points:
                if not isinstance(kp, dict):
                    continue
                title = kp.get("title", "（項目名なし）")
                comment = kp.get("comment", "")
                importance = kp.get("importance", "medium")
                if importance not in importance_style:
                    importance = "medium"
                style = importance_style[importance]

                st.markdown(f"""
                <div class="key-point-card {style['card']}">
                    <span class="key-point-badge {style['badge']}">{style['label']}</span>
                    <div class="key-point-title">{title}</div>
                    <div class="key-point-comment">{comment}</div>
                </div>
                """, unsafe_allow_html=True)

        st.markdown(f"""
        <div class="conclusion-card">
            <div class="conclusion-label">🧭 まとめ</div>
            <div class="conclusion-text">{conclusion_text}</div>
        </div>
        """, unsafe_allow_html=True)


def render_result_page():
    st.markdown("<div class='form-title'>🤖 STEP 3 : ロボの比較結果ボード</div>", unsafe_allow_html=True)
    
    if not st.session_state.selected_funds:
        st.markdown("""
        <div style="background-color: #fff3e0; border: 2.5px solid #ffcc80; padding: 25px; border-radius: 14px; margin-top: 15px;">
            <p style="margin: 0; font-weight: bold; font-size: 22px; color: #b78103;">💡 比較するファンドがまだ選ばれておりません</p>
            <p style="margin: 10px 0 0 0; font-size: 18px; color: #555555;">上部メニューの「<b>🔍 STEP 2 : ファンドを選ぼう</b>」をクリックし、解説させたいファンドにチェックを入れてください。</p>
        </div>
        """, unsafe_allow_html=True)
        return

    cleaned_custom_key = st.session_state.custom_key.strip() if "custom_key" in st.session_state else ""
    active_api_key = cleaned_custom_key if cleaned_custom_key else EMBEDDED_API_KEY
    
    selected_data = {}
    for name in st.session_state.selected_funds:
        if name in st.session_state.uploaded_funds:
            fund_data = st.session_state.uploaded_funds[name]
            if isinstance(fund_data, dict):
                selected_data[name] = fund_data.get("text", "")
            else:
                selected_data[name] = fund_data

    # 選択ファンドが前回と異なる場合は解説初期化を保証
    current_selected = sorted(st.session_state.selected_funds)
    if sorted(st.session_state.last_selected_funds) != current_selected:
        st.session_state.generated_explanation = ""
        st.session_state.last_selected_funds = current_selected

    # 選択画面から引き継がれた現在の設定値を上部にサマライズ表示
    target_type = st.session_state.get("result_target_type", "顧客（お客様ご自身への直接説明）向け")
    
    if "顧客" in target_type:
        age_val = st.session_state.get("result_age_range", "30代〜40代")
        exp_val = st.session_state.get("result_experience", "初心者")
        purp_val = st.session_state.get("result_purpose", "長期資産形成")
        tol_val = st.session_state.get("result_tolerance", "普通")
        summary_text = f"{target_type} （年齢: {age_val} / 投資経験: {exp_val} / 目的: {purp_val} / 許容度: {tol_val}）"
    else:
        summary_text = target_type

    st.markdown(f'<div style="background-color: #f0f4f8; border-left: 5px solid #0081c9; padding: 12px 18px; border-radius: 4px; margin-bottom: 20px;"><span style="font-size: 16px; font-weight: bold; color: #0f4c75;">🎯 現在設定されている解説ターゲット：</span><span style="font-size: 16px; color: #1a1a1a;">{summary_text}</span><span style="font-size: 14px; color: #555555; margin-left: 15px;">※設定を切り替えたい場合は、STEP 2の画面へ戻って調整してください。</span></div>', unsafe_allow_html=True)
    
    # --- ■ 比較表示機能 ---
    # 比較表を作成するかどうかは、STEP 2の選択画面（AI比較解説開始ボタンの横）で事前に選択済み
    show_comparison_table = st.session_state.get("show_comparison_table", True)

    mismatch_warnings = []
    comparison_df_summary = None
    chart_funds, chart_risk = [], []

    if show_comparison_table:
        st.markdown("#### 🔲 ロボがまとめた横並び比較表")
        with st.spinner("AIロボが重要情報シートを精緻に解析し、最適な比較表を作成しております。少々お待ちください..."):
            row_items = [
                "運用会社", "金融商品の目的・機能", "投資対象（キーワード）",
                "商品組成に携わる事業者が想定する購入層", "想定顧客層（キーワード）",
                "リスクの内容", "リスク種別（キーワード）",
                "過去1年のリターン（実績値）", 
                "過去1年のリターン（対象期間・基準日）", 
                "過去5年のリターン（平均・実績値）", 
                "過去5年のリターン（最低・実績値）", 
                "過去5年のリターン（最高・実績値）", 
                "過去5年のリターン（対象期間・基準日）", 
                "購入時手数料", "信託報酬（年率）", 
                "換金解約の条件", 
                "当事業者（当行・当社・当金庫等）の利益とお客さまの利益が反する可能性", 
                "NISA対応（つみたて投資枠/成長投資枠）"
            ]
            
            json_response = get_ai_comparison_data(selected_data, active_api_key, mode="table")
            
            try:
                parsed_data = json.loads(json_response)
            except Exception:
                try:
                    cleaned_json = re.sub(r"^```json\s*|```$", "", json_response.strip(), flags=re.MULTILINE)
                    parsed_data = json.loads(cleaned_json)
                except Exception:
                    parsed_data = {}
            
            # 仮名の混入を徹底的に防止する自動クリーニングフィルターの適用
            parsed_data = clean_dummy_names_in_data(parsed_data, st.session_state.selected_funds)
            
            table_payload = {"比較項目（行）": ["ファンド名"] + row_items}
            
            for name in st.session_state.selected_funds:
                columns_values = [name]
                
                fund_obj = None
                for k in parsed_data.keys():
                    if k in name or name in k:
                        fund_obj = parsed_data[k]
                        break
                
                if not fund_obj and parsed_data:
                    keys_list = list(parsed_data.keys())
                    fund_idx = st.session_state.selected_funds.index(name)
                    if fund_idx < len(keys_list):
                        fund_obj = parsed_data[keys_list[fund_idx]]
                        
                for item in row_items:
                    matched_val = None
                    if fund_obj:
                        # 部分一致対応（主語が「当社」「当金庫」「当事業者」等へ変更された場合にも頑健にマッチングさせる）
                        if "当事業者（当行・当社・当金庫等）の利益とお客さまの利益が反する可能性" in item or "利益が反する可能性" in item:
                            for key_in_obj in fund_obj.keys():
                                if "利益が反する" in key_in_obj or "利益相反" in key_in_obj or "反する可能性" in key_in_obj:
                                    matched_val = fund_obj[key_in_obj]
                                    break
                        else:
                            matched_val = fund_obj.get(item)
                            # あいまい一致フォールバック
                            if matched_val is None:
                                for k, v in fund_obj.items():
                                    if k in item or item in k:
                                        matched_val = v
                                        break
                    
                    if matched_val is not None:
                        # 個別ファンドのセル内の文章にも正式名を適用
                        columns_values.append(replace_dummy_fund_names(str(matched_val), st.session_state.selected_funds))
                    else:
                        columns_values.append("記載なし（抽出スキップ）")
                
                table_payload[name] = columns_values

            comparison_df = pd.DataFrame(table_payload)

            # --- 基準日・対象期間の食い違い自動検出ロジック ---
            if len(st.session_state.selected_funds) > 1:
                try:
                    p1_row = comparison_df[comparison_df["比較項目（行）"] == "過去1年のリターン（対象期間・基準日）"]
                    if not p1_row.empty:
                        p1_dates = [str(p1_row.iloc[0].iloc[col_idx]).strip() if hasattr(p1_row.iloc[0], 'iloc') else str(p1_row.values[0][col_idx]).strip() for col_idx in range(1, len(comparison_df.columns))]
                        p1_dates_clean = [d for d in p1_dates if d and "記載なし" not in d and "抽出スキップ" not in d]
                        if len(set(p1_dates_clean)) > 1:
                            mismatch_warnings.append(f"**過去1年の実績リターン算出のタイミング（期間・基準日）**が異なっております（検出された日付表記: {', '.join(set(p1_dates_clean))}）")
                except Exception:
                    pass


            if len(st.session_state.selected_funds) > 1:
                try:
                    p5_row = comparison_df[comparison_df["比較項目（行）"] == "過去5年のリターン（対象期間・基準日）"]
                    if not p5_row.empty:
                        p5_dates = [str(p5_row.iloc[0].iloc[col_idx]).strip() if hasattr(p5_row.iloc[0], 'iloc') else str(p5_row.values[0][col_idx]).strip() for col_idx in range(1, len(comparison_df.columns))]
                        p5_dates_clean = [d for d in p5_dates if d and "記載なし" not in d and "抽出スキップ" not in d]
                        if len(set(p5_dates_clean)) > 1:
                            mismatch_warnings.append(f"**過去5年の実績リターン算出のタイミング（期間・基準日）**が異なっております（検出された日付表記: {', '.join(set(p5_dates_clean))}）")
                except Exception:
                    pass

            fund_names = st.session_state.selected_funds

            # --- 🌟 コンパクト比較表（デフォルト表示・6項目のみ） ---
            summary_rows = [
                ["投資対象"] + [get_cell(comparison_df, "投資対象（キーワード）", f) for f in fund_names],
                ["想定顧客層"] + [get_cell(comparison_df, "想定顧客層（キーワード）", f) for f in fund_names],
                ["実質コスト（購入手数料＋信託報酬 目安）"] + [
                    compute_effective_cost(get_cell(comparison_df, "購入時手数料", f), get_cell(comparison_df, "信託報酬（年率）", f))
                    for f in fund_names
                ],
                ["リスク種別"] + [get_cell(comparison_df, "リスク種別（キーワード）", f) for f in fund_names],
                ["過去5年のリターン（平均・実績値）"] + [get_cell(comparison_df, "過去5年のリターン（平均・実績値）", f) for f in fund_names],
                ["NISA対象の有無"] + [simplify_nisa(get_cell(comparison_df, "NISA対応（つみたて投資枠/成長投資枠）", f)) for f in fund_names],
            ]
            comparison_df_summary = pd.DataFrame(summary_rows, columns=comparison_df.columns)

            # コンパクト比較表を描画
            custom_table_html_summary = render_custom_html_table(comparison_df_summary, parsed_data)
            st.markdown('<div class="scroll-table-container">', unsafe_allow_html=True)
            st.markdown(custom_table_html_summary, unsafe_allow_html=True)
            st.markdown('</div>', unsafe_allow_html=True)

            # --- 📊 リスク・リターン散布図（バブルチャート） ---
            chart_funds, chart_avg, chart_risk, chart_min, chart_max = [], [], [], [], []
            for f in fund_names:
                avg_val = parse_numeric_value(get_cell(comparison_df, "過去5年のリターン（平均・実績値）", f))
                min_val = parse_numeric_value(get_cell(comparison_df, "過去5年のリターン（最低・実績値）", f))
                max_val = parse_numeric_value(get_cell(comparison_df, "過去5年のリターン（最高・実績値）", f))
                if avg_val is not None and min_val is not None and max_val is not None:
                    chart_funds.append(f)
                    chart_avg.append(avg_val)
                    chart_risk.append(round(max_val - min_val, 2))
                    chart_min.append(min_val)
                    chart_max.append(max_val)

            if len(chart_funds) >= 1:
                st.markdown("<div style='margin-top: 10px;'></div>", unsafe_allow_html=True)
                st.markdown("##### 📊 リスク・リターン散布図（過去5年間の実績ベース）")
                st.caption("横軸：過去5年の最低〜最高リターンの値ブレ幅（簡易リスク指標）／縦軸：過去5年の平均リターン")

                # 🎨 ファンドごとに異なる色を割り当てるカラーパレット
                color_palette = [
                    "#e64980", "#4c6ef5", "#12b886", "#f59f00", "#7950f2",
                    "#fa5252", "#15aabf", "#82c91e", "#e8590c", "#1c7ed6",
                ]

                # 軸の見切れ防止のため、データ範囲に余白（パディング）を持たせる
                x_pad = max((max(chart_risk) - min(chart_risk)) * 0.18, 1.5)
                y_pad = max((max(chart_avg) - min(chart_avg)) * 0.28, 2.0)
                x_range = [max(0, min(chart_risk) - x_pad), max(chart_risk) + x_pad]
                y_range = [min(chart_avg) - y_pad, max(chart_avg) + y_pad]

                fig = go.Figure()

                for idx, f in enumerate(chart_funds):
                    color = color_palette[idx % len(color_palette)]
                    fig.add_trace(go.Scatter(
                        x=[chart_risk[idx]],
                        y=[chart_avg[idx]],
                        mode="markers+text",
                        name=f,
                        text=[f],
                        textposition="top center",
                        textfont=dict(size=22, color=color, family="Arial Black"),
                        marker=dict(size=34, color=color, line=dict(width=2.5, color="#ffffff"), opacity=0.92),
                        customdata=[[chart_min[idx], chart_max[idx]]],
                        hovertemplate="<b>%{text}</b><br>平均リターン: %{y:.1f}%<br>値ブレ幅: %{x:.1f}pt（最低%{customdata[0]:.1f}%〜最高%{customdata[1]:.1f}%）<extra></extra>",
                    ))
                fig.update_layout(
                    xaxis_title="<b>リスク（過去5年の値ブレ幅：最高－最低、pt）</b>",
                    yaxis_title="<b>平均リターン（過去5年、%）</b>",
                    height=520,
                    margin=dict(l=10, r=10, t=40, b=10),
                    plot_bgcolor="#f8fafc",
                    paper_bgcolor="#ffffff",
                    font=dict(size=19),
                    showlegend=True,
                    legend=dict(orientation="h", yanchor="top", y=-0.18, xanchor="center", x=0.5, font=dict(size=19)),
                    hoverlabel=dict(font_size=19),
                )
                fig.update_xaxes(
                    gridcolor="#e5e7eb", zeroline=True, zerolinecolor="#cbd5e1", zerolinewidth=1.5,
                    range=x_range, tickfont=dict(size=20), title_font=dict(size=22),
                    ticksuffix="pt",
                )
                fig.update_yaxes(
                    gridcolor="#e5e7eb", zeroline=True, zerolinecolor="#cbd5e1", zerolinewidth=1.5,
                    range=y_range, tickfont=dict(size=20), title_font=dict(size=22),
                    ticksuffix="%",
                )
                st.plotly_chart(fig, use_container_width=True)
                st.markdown("<div style='margin-bottom: 15px;'></div>", unsafe_allow_html=True)
            else:
                st.info("グラフ描画に必要な過去5年リターンの数値データが不足しているため、リスク・リターン散布図は表示されません。")

            # --- 📋 詳細な比較表（全項目）は折りたたみ表示 ---
            with st.expander(f"📋 詳細な比較表を見る（全{len(row_items)}項目・クリックで展開）", expanded=False):
                custom_table_html = render_custom_html_table(comparison_df, parsed_data)
                st.markdown('<div class="scroll-table-container">', unsafe_allow_html=True)
                st.markdown(custom_table_html, unsafe_allow_html=True)
                st.markdown('</div>', unsafe_allow_html=True)

            # --- ⚠️ 基準日不一致に関する警告・注意喚起の表示 ---
            if mismatch_warnings:
                st.markdown("""
                <div style="background-color: #fff3e0; border: 2.5px solid #ffcc80; padding: 22px; border-radius: 12px; margin-bottom: 30px; box-shadow: 0 4px 6px rgba(0,0,0,0.02); color: #555555;">
                    <p style="margin: 0 0 10px 0; font-weight: 900; font-size: 21px; color: #e65100; display: flex; align-items: center; gap: 8px;">
                        <span>⚠️</span> 実績データの集計時期のズレに関するお知らせ
                    </p>
                    <p style="margin: 0 0 12px 0; font-size: 18px; line-height: 1.5;">
                        選択されたファンド間で、実績リターン算出のタイミング（期間・基準日）に差異があることをロボが検出いたしました。
                    </p>
                    <ul style="margin: 0 0 12px 0; padding-left: 24px; font-size: 18px; line-height: 1.6;">
                """ + "".join([f"<li style='margin-bottom: 6px;'>{w}</li>" for w in mismatch_warnings]) + """
                    </ul>
                    <p style="margin: 0; font-size: 16px; font-style: italic; line-height: 1.4;">
                        ※集計時期が異なるため、単純なリターン数値の大小のみで性能を断定せず、比較の際には注意を払う必要があります。
                    </p>
                </div>
                """, unsafe_allow_html=True)
    else:
        st.info("比較表の作成をスキップしました。下部の解説レポートは選択されたファンドの重要情報シートをもとに直接生成されます。")

    # --- ■ AI解説機能 ---
    st.markdown("---")
    st.markdown("#### 🤖 金融AIアシスタントによる詳細解説レポート")

    # 比較結果画面が表示された流れでそのまま、解説レポートをバックグラウンド自動作成
    if not st.session_state.generated_explanation:
        # ターゲットに合わせた動的プロンプトの合成
        target_persona_instruction = ""
        selected_age = st.session_state.get("result_age_range", "30代〜40代")
        selected_experience = st.session_state.get("result_experience", "初心者")
        selected_purpose = st.session_state.get("result_purpose", "長期資産形成")
        selected_tolerance = st.session_state.get("result_tolerance", "普通")
        selected_horizon = st.session_state.get("result_horizon", "特にこだわらない")
        selected_fx = st.session_state.get("result_fx_tolerance", "特にこだわらない")
        selected_nisa_pref = st.session_state.get("result_nisa_pref", "特にこだわらない")
        selected_core_satellite_pref = st.session_state.get("result_core_satellite_pref", "特にこだわらない")
        selected_avoid_tags = st.session_state.get("result_avoid_tags", [])
        selected_existing_assets = st.session_state.get("result_existing_assets", [])
        selected_asset_scale = st.session_state.get("result_asset_scale", "回答しない")
        selected_free_text = st.session_state.get("result_free_text", "").strip()
        
        if "担当者" in target_type:
            target_persona_instruction = """
【解説ターゲット：金融機関の担当者（行員・アドバイザー等向け提案シナリオ）】
この解説 is、お客様へ適切な提案・アプローチを行う担当者（プロフェッショナル）に向けたものです。
・「顧客本位の業務運営」の基本原則に則り、客観的なファクトに基づいた中立・論理的な提案の切り口を授けてください。
・担当者が実際にお客様に説明する際にすぐに使える具体的な「話法（アプローチの質問やトークスクリプト）」を、心理面に寄り添いながら解説してください。
・難難なリスク指標（標準偏差、ボラティリティ、過去最大下落率など）について、担当者がお客様へ説明しやすいような身近な例え話や、専門用語の平易な翻訳フレーズを具体的に伝授してください。
・「魅力的」などの主観的感想は一切排除し、完全に客観的事実に基づいたロジカルな提案アプローチを提案してください。
"""
        else:
            exp_detail = ""
            if "初心者" in selected_experience:
                exp_detail = "投資に関する前提知識が浅いため、あらゆる専門用語（信託報酬やボラティリティなど）について、日常的な例え（例：維持コストをスマートフォンの月額基本料に例えるなど）に完全に翻訳して解説してください。"
            elif "中級者" in selected_experience:
                exp_detail = "基本的な用語や仕組みは理解されています。一歩踏み込んだ仕組み（信託報酬の差が長期の複利効果に与える影響や、5年リターンの上振れ・下振れの具体的なブレ幅から読み解くリスク効率性の数値など）についてロジカルに解説してください。"
            else:
                exp_detail = "投資経験が極めて豊富で上級者レベルです。ポートフォリオ全体への相関効果、アセットクラス特有 of ベータ値やシャープレシオなどの金融工学的なデータも交え、緻密で高度なロジカル分散投資分析を提供してください。"

            extra_profile_lines = []
            if selected_horizon != "特にこだわらない":
                extra_profile_lines.append(f"・想定運用期間：{selected_horizon}")
            if selected_fx != "特にこだわらない":
                extra_profile_lines.append(f"・為替リスクの許容度：{selected_fx}")
            if selected_nisa_pref != "特にこだわらない":
                extra_profile_lines.append(f"・NISA活用の意向：{selected_nisa_pref}")
            if selected_core_satellite_pref != "特にこだわらない":
                extra_profile_lines.append(f"・コア・サテライト運用の考え方：{selected_core_satellite_pref}")
            if selected_existing_assets:
                extra_profile_lines.append(f"・現在保有している金融資産：{'、'.join(selected_existing_assets)}")
            if selected_asset_scale != "回答しない":
                extra_profile_lines.append(f"・保有金融資産の規模目安：{selected_asset_scale}")
            if selected_avoid_tags:
                extra_profile_lines.append(f"・除外を希望する条件：{'、'.join(selected_avoid_tags)}")
            if selected_free_text:
                extra_profile_lines.append(f"・その他の自由記述（担当者からの補足情報）：{selected_free_text}")
            extra_profile_text = ("\n" + "\n".join(extra_profile_lines)) if extra_profile_lines else ""

            target_persona_instruction = f"""
【解説ターゲット：顧客（お客様ご自身への直接丁寧なアドバイス）】
この解説は、以下のプロフィールを持つお客様ご自身が直接お読みになり、意思決定を行うための丁寧な解説です。
・お名前やファンド仮名は絶対に使わず、正式なファンド名を用いて客観的にお話しください。
・お客様の年齢層：{selected_age}
・お客様の投資経験：{selected_experience} （解説難度アプローチ：{exp_detail}）
・お客様の投資目的：{selected_purpose}
・お客様のリスク許容度：{selected_tolerance}{extra_profile_text}

上記のプロファイルに極めて高度に寄り添った、親切で説得力のある説明を行ってください。
・特にお客様の年齢層（若年層であれば長期投資の複利メリット、シニア層であれば流動性の確保や取り崩しフェーズへの適応など）に考慮し、投資期間を想定した最適なアプローチをアドバイスに含めてください。
・お客様の「投資目的」と照らし合わせ、今回の各ファンドが資産形成の目標達成にどう機能するのか（あるいはどのような点で注意が必要か）を丁寧に整理してください。
・お客様の「リスク許容度」と照らし合わせて、5年の実績最低・最高値から想定されるボラティリティ（ブレ幅）が、このお客様の許容範囲内に収まるアセットバランスなのかを論理的かつ誠実に分析・解説してください。
・上記の追加項目（運用期間・為替許容度・NISA意向・コア・サテライト運用の考え方・除外条件・自由記述）が設定されている場合は、それらの内容も踏まえて整合性のとれた解説をしてください。ただし、記載のない前提を勝手に補って断定しないでください。
・「魅力的」などの売り込み・押し売り表現は徹底的に排除し、お客様が主体的に賢い判断を下せるよう、中立的かつ客観的なファクトベース of 道標となる説明に徹してください。

【コア・サテライト運用の考え方（分類定義）】
各ファンドを比較・解説する際は、以下の定義に基づいて「コア資産」「サテライト資産」のいずれに該当するかを踏まえて説明してください（この定義は絞り込み機能で使用しているものと同一です。表記も統一してください）。
・サテライト資産：テーマ型ファンド（脱炭素・テクノロジー・サイバーセキュリティ・インパクト投資等）、新興国株式・債券、REIT（不動産投資信託証券）、ハイ・イールド債、ブル・ベア型、オルタナティブ投資（コモディティ・ヘッジファンド等）
・コア資産：上記に該当しない、全世界株式・先進国株式・国内株式インデックスや伝統的な債券等の基本的な資産クラス
・お客様が「コア・サテライト運用の考え方」を選択されている場合は、比較対象ファンドがそれぞれコア資産・サテライト資産のどちらに該当するかを明示し、お客様のご希望（安定重視でコア中心か、プラスアルファを狙いサテライトも組み入れるか）との整合性を具体的に解説してください。
・断定的な配分比率の推奨（「コア○％・サテライト○％にすべき」等）は避け、あくまで各ファンドの位置づけの説明と、お客様の意向との整合性の解説に留めてください。
"""

        with st.spinner("金融AIアシスタントが重要情報シートを精緻に分析し、詳細解説レポートを自動作成しております。今しばらくお待ちください..."):
            raw_ai_response = get_ai_comparison_data(
                selected_data, 
                active_api_key, 
                mode="analysis", 
                mismatch_warnings=mismatch_warnings,
                target_instruction=target_persona_instruction
            )

            # AIの応答をJSONとしてパース（万が一コードブロック記号が混入していても除去してから再試行）
            try:
                parsed_analysis = json.loads(raw_ai_response)
            except Exception:
                try:
                    cleaned_json = re.sub(r"^```json\s*|```$", "", raw_ai_response.strip(), flags=re.MULTILINE)
                    parsed_analysis = json.loads(cleaned_json)
                except Exception:
                    parsed_analysis = {
                        "summary": "解説データの取得に失敗いたしました。お手数ですが、時間をおいて再度お試しください。",
                        "key_points": [],
                        "conclusion": ""
                    }

            st.session_state.generated_explanation = parsed_analysis
            st.rerun()  # 状態を即時にセッションへマッピング

    else:
        # すでに生成・保持されているレポートが存在する場合は即時描画
        render_analysis_report(st.session_state.generated_explanation, st.session_state.selected_funds)

    st.markdown("<br>", unsafe_allow_html=True)


