    if "custom_key" not in st.session_state:
        st.session_state.custom_key = ""
        
    cleaned_custom_key = st.session_state.custom_key.strip()
    
    # グローバル変数を参照・更新してNameErrorを根絶します
    ACTIVE_API_KEY = cleaned_custom_key if cleaned_custom_key else EMBEDDED_API_KEY

    # --- 🟢 稼働中のAPIキーの優先状態ステータスバーを常時上部に表示 ---
    display_api_key_status_bar()

    # --- 🗺️ 3ステップ式・横並びタブナビゲーションメニューの表示 ---
    col_nav1, col_nav2, col_nav3 = st.columns(3)
    
    current_page = st.session_state.current_page
    has_uploaded_funds = len(st.session_state.uploaded_funds) > 0
    has_selected_funds = len(st.session_state.selected_funds) > 0

    with col_nav1:
        # STEP 1: PDF登録 ＆ 鍵設定 (いつでも移動可能)
        if st.button("⚙️ STEP 1 : PDF追加・鍵設定", key="nav_admin_step", use_container_width=True):
            st.session_state.current_page = "admin"
            st.rerun()

    with col_nav2:
        # STEP 2: ファンド比較選択 (プリセット常時読み込みのため常に利用可能)
        if st.button("🔍 STEP 2 : ファンドを選択する", key="nav_select_step", use_container_width=True):
            st.session_state.current_page = "selection"
            st.rerun()

    with col_nav3:
        # STEP 3: AI解説結果
        if not has_selected_funds:
            st.button("🤖 STEP 3 : ロボの比較結果（未選択）", key="nav_result_step_disabled", disabled=True, use_container_width=True)
        else:
            if st.button("🤖 STEP 3 : ロボの比較結果を見る", key="nav_result_step", use_container_width=True):
                st.session_state.current_page = "result"
