    st.markdown("<hr style='margin: 15px 0 25px 0; border: 1px solid #d1d5db;'>", unsafe_allow_html=True)

    # --- 画面描画の切り替え (st.session_state で complete_synced 同期制御) ---
    if st.session_state.current_page == "admin":
        render_admin_content(ACTIVE_API_KEY)
    elif st.session_state.current_page == "result":
        render_result_page()
    else:
        render_selection_content(ACTIVE_API_KEY)


